<?php
/** @var array<string, mixed> $attributes */
declare( strict_types=1 ); if ( ! defined( 'ABSPATH' ) ) { exit; }
$nextsaas_plans = nextsaas_items( $attributes, 'plans' );
?>
<section <?php echo nextsaas_section_attrs( 'pricing-pricing', $attributes, array( 'section', 'pricing' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?> data-monthly-notice="<?php echo esc_attr( nextsaas_attr( $attributes, 'monthlyNotice' ) ); ?>" data-yearly-notice="<?php echo esc_attr( nextsaas_attr( $attributes, 'yearlyNotice' ) ); ?>" data-currency="<?php echo esc_attr( nextsaas_attr( $attributes, 'currency', '$' ) ); ?>">
<div class="container"><div class="billing"><div class="billing-toggle" role="group" aria-label="<?php echo esc_attr( nextsaas_attr( $attributes, 'billingLabel' ) ); ?>"><button aria-pressed="true" data-billing="monthly" data-nextsaas-rich="monthlyLabel"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'monthlyLabel' ) ); ?></button><button aria-pressed="false" data-billing="yearly" data-nextsaas-rich="yearlyLabel"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'yearlyLabel' ) ); ?></button></div><p data-nextsaas-rich="offerNote"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'offerNote' ) ); ?></p></div>
<div class="price-grid"><?php foreach ( $nextsaas_plans as $nextsaas_i => $nextsaas_plan ) : ?><article class="plan<?php echo ! empty( $nextsaas_plan['featured'] ) ? ' featured' : ' '; ?>"><span class="meta" data-nextsaas-rich="plans.<?php echo esc_attr( (string) $nextsaas_i ); ?>.meta"><?php echo nextsaas_rich( (string) ( $nextsaas_plan['meta'] ?? '' ) ); ?></span><h3 data-nextsaas-rich="plans.<?php echo esc_attr( (string) $nextsaas_i ); ?>.name"><?php echo nextsaas_rich( (string) ( $nextsaas_plan['name'] ?? '' ) ); ?></h3><p data-nextsaas-rich="plans.<?php echo esc_attr( (string) $nextsaas_i ); ?>.description"><?php echo nextsaas_rich( (string) ( $nextsaas_plan['description'] ?? '' ) ); ?></p><div class="price num"><span data-monthly="<?php echo esc_attr( (string) ( $nextsaas_plan['monthlyPrice'] ?? '' ) ); ?>" data-yearly="<?php echo esc_attr( (string) ( $nextsaas_plan['yearlyPrice'] ?? '' ) ); ?>"><?php echo esc_html( nextsaas_attr( $attributes, 'currency', '$' ) . (string) ( $nextsaas_plan['monthlyPrice'] ?? '' ) ); ?></span><small data-nextsaas-rich="plans.<?php echo esc_attr( (string) $nextsaas_i ); ?>.unit"><?php echo nextsaas_rich( (string) ( $nextsaas_plan['unit'] ?? '' ) ); ?></small></div><div class="price-note" data-monthly="<?php echo esc_attr( (string) ( $nextsaas_plan['monthlyNote'] ?? '' ) ); ?>" data-yearly="<?php echo esc_attr( (string) ( $nextsaas_plan['yearlyNote'] ?? '' ) ); ?>"><?php echo esc_html( (string) ( $nextsaas_plan['monthlyNote'] ?? '' ) ); ?></div><ul><?php foreach ( (array) ( $nextsaas_plan['features'] ?? array() ) as $nextsaas_feature ) : ?><li><?php echo nextsaas_icon( 'check' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?><span><?php echo esc_html( (string) ( $nextsaas_feature['text'] ?? '' ) ); ?></span></li><?php endforeach; ?></ul><?php echo nextsaas_cta( array( 'label'=>(string)( $nextsaas_plan['ctaLabel']??'' ), 'url'=>(string)( $nextsaas_plan['ctaUrl']??'' ), 'variant'=>(string)( $nextsaas_plan['ctaVariant']??'secondary' ), 'icon'=>true ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?></article><?php endforeach; ?></div><p class="pricing-note" id="billing-note" aria-live="polite" data-nextsaas-rich="monthlyNotice"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'monthlyNotice' ) ); ?></p></div></section>
